import 'dart:math' as math;

import '../constants.dart';

/// Sound effects. Files live in `assets/audio/` and are generated by
/// `tool/make_sfx.dart`.
enum Sfx {
  place,
  clear,
  invalid,
  gameOver,
  newBest,

  /// Menu sounds (see [UiSounds] in game_core).
  uiTap,
  uiToggle,
}

const Map<Sfx, String> kSfxFiles = {
  Sfx.place: 'place.wav',
  Sfx.clear: 'clear.wav',
  Sfx.invalid: 'invalid.wav',
  Sfx.gameOver: 'game_over.wav',
  Sfx.newBest: 'new_best.wav',
  Sfx.uiTap: 'ui_tap.wav',
  Sfx.uiToggle: 'ui_toggle.wav',
};

/// Playback rate for the clear sound at [streak]: steps up the musical
/// intervals in [kClearStreakSemitones], then stays at the top.
double clearRate(int streak) {
  final steps = kClearStreakSemitones;
  final semis = steps[streak.clamp(0, steps.length - 1)];
  return math.pow(2, semis / 12).toDouble();
}
